[
  {
    "text": "OpenForgeRL uses a lightweight proxy to record harness model calls as training data for a standard RL codebase, enabling end-to-end training of harness-based agents.",
    "topic": "training framework"
  },
  {
    "text": "OpenForgeRL employs a Kubernetes orchestrator to run each rollout in its own remote container, allowing training on any harness in any environment at scale.",
    "topic": "orchestration"
  },
  {
    "text": "OpenForgeClaw, trained with OpenForgeRL, achieves 31.7 pass³ and 55.9 pass@3 on ClawEval and 33.7 on QwenClawBench using only hundreds to a few thousand tasks.",
    "topic": "tool-based agent performance"
  },
  {
    "text": "OpenForgeGUI, trained with OpenForgeRL, reaches 37.7 on OSWorld-Verified, 63.0 on Online-Mind2Web, and 72.3 on WebVoyager, outperforming open baselines of similar size on nearly all benchmarks.",
    "topic": "GUI-based agent performance"
  },
  {
    "text": "Reinforcement learning (RL) improves agentic reliability, such as self-verification, tool coverage, and completing multi-step plans, though critical abilities like error recovery remain weak.",
    "topic": "RL impact on agent reliability"
  }
]
